// Package serviceacct manages tenant service accounts: machine identities that obtain access tokens with the OAuth 2.0
// client credentials grant (client_id = service account ID) and can hold role assignments (ADR-0037). Secrets are
// generated by Porch, shown once and stored only as HMACs under the keyring token key.
package serviceacct

import (
	"context"
	"crypto/hmac"
	"database/sql"
	"encoding/json"
	"errors"
	"time"

	"github.com/aurimasniekis/go-porch/internal/apperr"
	"github.com/aurimasniekis/go-porch/internal/apps"
	"github.com/aurimasniekis/go-porch/internal/audit"
	"github.com/aurimasniekis/go-porch/internal/domain"
	"github.com/aurimasniekis/go-porch/internal/ids"
	"github.com/aurimasniekis/go-porch/internal/keyring"
	"github.com/aurimasniekis/go-porch/internal/outbox"
	"github.com/aurimasniekis/go-porch/internal/session"
	"github.com/aurimasniekis/go-porch/internal/store"
	"github.com/aurimasniekis/go-porch/internal/store/db"
	"github.com/aurimasniekis/go-porch/internal/tenancy"
)

// SecretPrefix marks service-account secrets (secret scanners can match it).
const SecretPrefix = "porch_sa_"

const macDomain = "porch/sa-secret/v1|"

// ErrNotFound is returned for unknown service accounts.
var ErrNotFound = apperr.New(apperr.CodeNotFound, "service account not found")

// Account is a service account (never includes the secret).
type Account struct {
	ID             string     `json:"id"`
	TenantID       string     `json:"tenant_id"`
	Slug           string     `json:"slug"`
	Name           string     `json:"name"`
	Description    string     `json:"description"`
	Enabled        bool       `json:"enabled"`
	SecretHint     string     `json:"secret_hint"`
	Audiences      []string   `json:"audiences"`
	AccessTokenTTL int64      `json:"access_token_ttl_seconds"`
	LastUsedAt     *time.Time `json:"last_used_at,omitempty"`
	Version        int64      `json:"version"`
	ManagedBy      string     `json:"managed_by"`
	LastChangedBy  string     `json:"last_changed_by,omitempty"`
	CreatedAt      time.Time  `json:"created_at"`
	UpdatedAt      time.Time  `json:"updated_at"`
}

// FromRow converts a row.
func FromRow(r db.ServiceAccount) Account {
	var aud []string
	_ = json.Unmarshal([]byte(r.Audiences), &aud)
	if aud == nil {
		aud = []string{}
	}
	return Account{ID: r.ID, TenantID: r.TenantID, Slug: r.Slug, Name: r.Name, Description: r.Description, Enabled: r.Enabled == 1,
		SecretHint: r.SecretHint, Audiences: aud, AccessTokenTTL: r.AccessTokenTtlSecs, LastUsedAt: domain.OptMicros(r.LastUsedAt),
		Version: r.Version, ManagedBy: r.ManagedBy, LastChangedBy: r.LastChangedBy.String, CreatedAt: domain.FromMicros(r.CreatedAt),
		UpdatedAt: domain.FromMicros(r.UpdatedAt)}
}

// Params create or update a service account. Nil pointers leave fields unchanged on update.
type Params struct {
	Slug           string
	Name           *string
	Description    *string
	Enabled        *bool
	Audiences      []string
	AccessTokenTTL *time.Duration
	IfVersion      int64
}

// Service manages service accounts.
type Service struct {
	s     *store.Store
	kr    *keyring.Keyring
	audit *audit.Writer
}

// New returns the service.
func New(s *store.Store, kr *keyring.Keyring, a *audit.Writer) *Service {
	return &Service{s: s, kr: kr, audit: a}
}

func (svc *Service) newSecret() (secret string, mac []byte, hint string, err error) {
	r, err := session.RandomToken()
	if err != nil {
		return "", nil, "", err
	}
	secret = SecretPrefix + r
	mac, err = svc.kr.MAC(keyring.PurposeToken, []byte(macDomain+secret))
	return secret, mac, secret[len(secret)-4:], err
}

// VerifySecret checks a secret in constant time against every non-retired token key version.
func (svc *Service) VerifySecret(r db.ServiceAccount, secret string) bool {
	if len(r.SecretMac) == 0 || secret == "" || len(secret) > 256 {
		return false
	}
	macs, err := svc.kr.MACAll(keyring.PurposeToken, []byte(macDomain+secret))
	if err != nil {
		return false
	}
	ok := false
	for _, m := range macs {
		if hmac.Equal(m, r.SecretMac) {
			ok = true
		}
	}
	return ok
}

func validate(p *Params, create bool, v *apperr.Validation) {
	if create && !domain.ValidSlug(p.Slug) {
		v.Add("slug", "must be lowercase letters, digits or inner hyphens")
	}
	if p.Name != nil {
		*p.Name = domain.CleanName("name", *p.Name, v)
	}
	if p.Description != nil && len(*p.Description) > 2000 {
		v.Add("description", "at most 2000 characters")
	}
	if len(p.Audiences) > 20 {
		v.Add("audiences", "at most 20 audiences")
	}
	for _, a := range p.Audiences {
		if !apps.ValidAudience(a) {
			v.Add("audiences", "%q is not a valid audience (use an absolute URI or a short identifier)", a)
		}
	}
	if p.AccessTokenTTL != nil && (*p.AccessTokenTTL < time.Minute || *p.AccessTokenTTL > time.Hour) {
		v.Add("access_token_ttl_seconds", "must be between 60 and 3600")
	}
}

func (svc *Service) tx(ctx context.Context, name string, ch domain.Change, sc tenancy.Scope, ev audit.Event, fn func(tx *store.Tx) error, opts ...func(*audit.Event)) error {
	if !sc.Valid() {
		return tenancy.ErrNoAccess
	}
	return svc.s.W().TxNamed(ctx, name, func(tx *store.Tx) error {
		if err := fn(tx); err != nil {
			return err
		}
		for _, o := range opts {
			o(&ev)
		}
		ev.Actor, ev.TenantID = ch.Actor, sc.TenantID()
		if _, err := svc.audit.Append(ctx, tx, ev); err != nil {
			return err
		}
		_, err := outbox.Enqueue(ctx, tx, outbox.Event{Area: "iam", Entity: "service_account", Action: ev.Action[len("service_account."):],
			TenantID: sc.TenantID(), Payload: map[string]any{"service_account_id": ev.Target.ID}})
		return err
	})
}

// Created is a new service account with its secret (shown once).
type Created struct {
	Account Account
	Secret  string
}

// Create adds a service account to the tenant.
func (svc *Service) Create(ctx context.Context, ch domain.Change, sc tenancy.Scope, p Params) (Created, error) {
	var v apperr.Validation
	if p.Name == nil {
		p.Name = new(string)
	}
	validate(&p, true, &v)
	if err := v.Err(); err != nil {
		return Created{}, err
	}
	secret, mac, hint, err := svc.newSecret()
	if err != nil {
		return Created{}, err
	}
	ttl := int64(600)
	if p.AccessTokenTTL != nil {
		ttl = int64(*p.AccessTokenTTL / time.Second)
	}
	desc := ""
	if p.Description != nil {
		desc = *p.Description
	}
	aud, _ := json.Marshal(nonNil(p.Audiences))
	id := ids.New(ids.ServiceAccount)
	err = svc.tx(ctx, "serviceacct.create", ch, sc, audit.Event{Action: "service_account.created", Target: audit.Target{Type: "service_account", ID: id},
		Details: map[string]any{"slug": p.Slug}}, func(tx *store.Tx) error {
		err := tx.Q.InsertServiceAccount(ctx, db.InsertServiceAccountParams{ID: id, TenantID: sc.TenantID(), Slug: p.Slug, Name: *p.Name,
			Description: desc, SecretMac: mac, SecretHint: hint, Audiences: string(aud), AccessTokenTtlSecs: ttl, ManagedBy: ch.Managed(),
			LastChangedBy: domain.NullStr(ch.ChangedBy()), CreatedAt: tx.NowMicros(), UpdatedAt: tx.NowMicros()})
		if store.IsConstraint(err) {
			return apperr.New(apperr.CodeAlreadyExists, "service account %q exists", p.Slug)
		}
		return err
	})
	if err != nil {
		return Created{}, err
	}
	a, err := svc.Get(ctx, sc, id)
	return Created{Account: a, Secret: secret}, err
}

// Update changes name, description, enabled, audiences or token lifetime.
func (svc *Service) Update(ctx context.Context, ch domain.Change, sc tenancy.Scope, ref string, p Params) (Account, error) {
	var v apperr.Validation
	validate(&p, false, &v)
	if err := v.Err(); err != nil {
		return Account{}, err
	}
	var id string
	err := svc.tx(ctx, "serviceacct.update", ch, sc, audit.Event{Action: "service_account.updated"}, func(tx *store.Tx) error {
		r, err := svc.getTx(ctx, tx, sc, ref)
		if err != nil {
			return err
		}
		id = r.ID
		if err := domain.IfMatch(p.IfVersion, r.Version); err != nil {
			return err
		}
		up := db.UpdateServiceAccountParams{Name: r.Name, Description: r.Description, Enabled: r.Enabled, Audiences: r.Audiences,
			AccessTokenTtlSecs: r.AccessTokenTtlSecs, ManagedBy: ch.Managed(), LastChangedBy: domain.NullStr(ch.ChangedBy()), UpdatedAt: tx.NowMicros(),
			TenantID: sc.TenantID(), ID: r.ID, Version: r.Version}
		if p.Name != nil {
			up.Name = *p.Name
		}
		if p.Description != nil {
			up.Description = *p.Description
		}
		if p.Enabled != nil {
			up.Enabled = 0
			if *p.Enabled {
				up.Enabled = 1
			}
		}
		if p.Audiences != nil {
			b, _ := json.Marshal(p.Audiences)
			up.Audiences = string(b)
		}
		if p.AccessTokenTTL != nil {
			up.AccessTokenTtlSecs = int64(*p.AccessTokenTTL / time.Second)
		}
		n, err := tx.Q.UpdateServiceAccount(ctx, up)
		if err == nil && n != 1 {
			return apperr.New(apperr.CodePrecondition, "service account changed concurrently")
		}
		return err
	}, withTarget(&id))
	if err != nil {
		return Account{}, err
	}
	return svc.Get(ctx, sc, id)
}

// RotateSecret issues a new secret; the old one stops working immediately.
func (svc *Service) RotateSecret(ctx context.Context, ch domain.Change, sc tenancy.Scope, ref string) (string, error) {
	secret, mac, hint, err := svc.newSecret()
	if err != nil {
		return "", err
	}
	var id string
	err = svc.tx(ctx, "serviceacct.rotate", ch, sc, audit.Event{Action: "service_account.secret_rotated"}, func(tx *store.Tx) error {
		r, err := svc.getTx(ctx, tx, sc, ref)
		if err != nil {
			return err
		}
		id = r.ID
		_, err = tx.Q.SetServiceAccountSecret(ctx, db.SetServiceAccountSecretParams{SecretMac: mac, SecretHint: hint, UpdatedAt: tx.NowMicros(),
			TenantID: sc.TenantID(), ID: r.ID})
		return err
	}, withTarget(&id))
	return secret, err
}

// Delete removes a service account and its role assignments.
func (svc *Service) Delete(ctx context.Context, ch domain.Change, sc tenancy.Scope, ref string, ifVersion int64) error {
	var id string
	return svc.tx(ctx, "serviceacct.delete", ch, sc, audit.Event{Action: "service_account.deleted"}, func(tx *store.Tx) error {
		r, err := svc.getTx(ctx, tx, sc, ref)
		if err != nil {
			return err
		}
		id = r.ID
		if err := domain.IfMatch(ifVersion, r.Version); err != nil {
			return err
		}
		if _, err := tx.Q.DeleteSubjectAssignments(ctx, db.DeleteSubjectAssignmentsParams{TenantID: sc.TenantID(), SubjectType: "service_account",
			SubjectID: r.ID}); err != nil {
			return err
		}
		if err := tx.Q.BumpAuthzEpoch(ctx, sc.TenantID()); err != nil {
			return err
		}
		_, err = tx.Q.DeleteServiceAccount(ctx, db.DeleteServiceAccountParams{TenantID: sc.TenantID(), ID: r.ID})
		return err
	}, withTarget(&id))
}

// withTarget lets a transaction fill in the audit target after resolving a reference.
func withTarget(id *string) func(*audit.Event) {
	return func(ev *audit.Event) { ev.Target = audit.Target{Type: "service_account", ID: *id} }
}

func (svc *Service) getTx(ctx context.Context, tx *store.Tx, sc tenancy.Scope, ref string) (db.ServiceAccount, error) {
	r, err := tx.Q.GetServiceAccount(ctx, db.GetServiceAccountParams{TenantID: sc.TenantID(), Ref: ref})
	if errors.Is(err, sql.ErrNoRows) {
		return r, ErrNotFound
	}
	return r, err
}

// List returns the tenant's service accounts.
func (svc *Service) List(ctx context.Context, sc tenancy.Scope) ([]Account, error) {
	if !sc.Valid() {
		return nil, tenancy.ErrNoAccess
	}
	rows, err := svc.s.R().ListServiceAccounts(ctx, sc.TenantID())
	if err != nil {
		return nil, err
	}
	out := make([]Account, 0, len(rows))
	for _, r := range rows {
		out = append(out, FromRow(r))
	}
	return out, nil
}

// Get returns one service account by ID or slug.
func (svc *Service) Get(ctx context.Context, sc tenancy.Scope, ref string) (Account, error) {
	if !sc.Valid() {
		return Account{}, tenancy.ErrNoAccess
	}
	r, err := svc.s.R().GetServiceAccount(ctx, db.GetServiceAccountParams{TenantID: sc.TenantID(), Ref: ref})
	if errors.Is(err, sql.ErrNoRows) {
		return Account{}, ErrNotFound
	}
	if err != nil {
		return Account{}, err
	}
	return FromRow(r), nil
}

func nonNil(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}
